const route=()=>location.hash.slice(1)||'home';
function persist(){history.replaceState({filters:{...state},scroll:window.scrollY,depth:history.state?.depth||0},'')}
function go(id){persist();state.point=null;history.pushState({filters:{...state},scroll:0,depth:(history.state?.depth||0)+1},'','#'+id);render();window.scrollTo(0,0)}
function comparison(m,type='mom'){const delta=current(m)-previous(m,type),v=m.kind==='rate'?delta:previous(m,type)===0?0:delta/Math.abs(previous(m,type))*100;const bad=m.lower?v>0:v<0;return `<span class="${bad?'red':'green'}">${m.unit==='家'?(delta>0?'+':'')+money(delta):signed(v)}${m.unit==='家'?'家':m.kind==='rate'?'pp':'%'}</span>`}
function changes(m){return `<div class="metric-changes"><span>环比 ${comparison(m)}</span><span>${m.sameStore?'同店同比':'同比'} ${comparison(m,'yoy')}</span></div>`}
function metricCard(id,small=false){const m=metrics[id],v=current(m);return `<button class="group-metric ${small?'small':''}" data-go="${id}"><div class="metric-label">${m.name}<span>›</span></div><div class="metric-number ${m.color||''}">${fmt(v,m)}<small>${unit(m)}</small></div>${m.target!==undefined?`<div class="metric-hint">目标 ${m.lower?'≤':'≥'}${m.target}${m.unit}</div>`:''}${changes(m)}</button>`}
function overviewGroup(name,icon,ids,note=''){return `<section class="overview-block overview-compact" aria-label="${name}指标"><div class="overview-columns"><h2>${icon}${name}</h2><span>本期</span><span>环比</span><span>同比</span><span></span></div>${ids.map(id=>{const m=metrics[id],v=current(m);return `<button class="overview-row" data-go="${id}" aria-label="${m.name} ${fmt(v,m)}${unit(m)}，环比 ${comparison(m).replace(/<[^>]+>/g,'')}，同比 ${comparison(m,'yoy').replace(/<[^>]+>/g,'')}，查看分析"><span class="overview-name">${m.name}<small>${unit(m)}</small></span><b class="overview-value" style="--digits:${fmt(v,m).length}">${fmt(v,m)}</b><span class="overview-delta">${comparison(m)}</span><span class="overview-delta">${comparison(m,'yoy')}</span><span class="overview-arrow" aria-hidden="true">›</span></button>`}).join('')}${note?`<p class="overview-note">${note}</p>`:''}</section>`}
function section(name,extra=''){return `<div class="section-title"><span>${name}</span><small>${extra}</small></div>`}
function dateTabs(){return `<div class="date-tabs" role="group" aria-label="日期类型">${[['day','日'],['week','周'],['month','月']].map(([id,n])=>`<button data-date-type="${id}" aria-pressed="${state.day===id}" class="${state.day===id?'selected':''}">${n}</button>`).join('')}</div>`}
function dateLabel(date,type=state.day){const d=parseDate(date),short=v=>`${Number(v.slice(5,7))}月${Number(v.slice(8))}日`;if(type==='month')return `${d.getUTCFullYear()}年${d.getUTCMonth()+1}月`;if(type==='week'){const {start,end}=weekRange(date),thursday=parseDate(shiftDate(start,3)),week=Math.ceil(((thursday- new Date(Date.UTC(thursday.getUTCFullYear(),0,1)))/86400000+1)/7),range=v=>`${start.slice(0,4)!==end.slice(0,4)?v.slice(0,4)+'/':''}${Number(v.slice(5,7))}/${Number(v.slice(8))}`;return `第${week}周 (${range(start)}–${range(end)})`}return `${short(date)} 周${'日一二三四五六'[d.getUTCDay()]}`}
function dateOptions(){const anchor=state.day==='week'?shiftDate(todayDate(),-1):state.date>'2026-09-18'?state.date:'2026-09-18',d=parseDate(anchor);const options=Array.from({length:state.day==='day'?31:12},(_,i)=>state.day==='month'?iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()-i,1))):state.day==='week'?shiftDate(anchor,-((d.getUTCDay()+6)%7)-i*7):shiftDate(anchor,-i));const selected=dateRange().start;return options.includes(selected)?options:[selected,...options]}
function datePicker(){const r=dateRange(),multiple=!!state.endDate&&(state.day==='week'?periodWeeks()>1:state.endDate!==state.date),label=multiple?(state.day==='month'?`${dateLabel(r.start)} – ${r.start.slice(0,4)===r.end.slice(0,4)?Number(r.end.slice(5,7))+'月':dateLabel(r.end)}`:`${r.start.replaceAll('-','/')} – ${r.end.replaceAll('-','/')}`):dateLabel(state.date);return `<details class="date-control" id="date-control"><summary class="date-trigger" id="date-open" aria-label="选择统计日期" title="${rangeText(r)}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v5m10-5v5M3 11h18"/></svg><span class="date-copy">${label}</span><svg class="date-caret" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg></summary><div class="date-popover">${dateTabs()}<div class="date-options ${state.day}" role="group" aria-label="选择日期">${dateOptions().map(date=>{const selected=!multiple&&(state.day==='day'?date===state.date:state.day==='month'?date.slice(0,7)===r.start.slice(0,7):date===r.start);return `<button data-date-value="${date}" aria-pressed="${selected}" class="${selected?'selected':''}">${dateLabel(date)}</button>`}).join('')}</div><button class="date-other" id="date-other">${state.day==='month'?'选择月份期间…':state.day==='day'?'选择日期区间…':'选择周期间…'}</button></div></details>`}
function filter(){return `<div class="hero date-only">${datePicker()}</div>`}
function homeHeader(title){return `<section class="dashboard-hero" aria-label="集团概况"><div class="group-identity"><span class="group-mark" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="10" y="4" width="13" height="24" rx="2"/><path d="M10 15H6a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h4m13-15h3a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2h-3M14 9h5m-5 5h5m-5 5h5m-5 5h5"/></svg></span><div class="group-name"><h1>${title}</h1><p>比格比萨餐饮集团</p></div></div><div class="group-badges" aria-label="集团规模"><span>6 大品牌</span><span>23 个城市</span><button data-go="stores" aria-label="${current(metrics.stores)}家在营门店，查看分析">${current(metrics.stores)} 家门店</button></div><div class="hero-periods">${datePicker()}</div></section>`}
function footer(){return '<footer class="footer">全部为模拟数据 · 点击指标可查看分析<br>金额与人数均为演示口径，不代表真实集团经营</footer>'}
const overviewIcons={'门店':'<svg class="overview-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 10v10h18V10M2 10l2-7h16l2 7M2 10a2.5 2.5 0 0 0 5 0 2.5 2.5 0 0 0 5 0 2.5 2.5 0 0 0 5 0 2.5 2.5 0 0 0 5 0M9 20v-6h6v6"/></svg>','员工':'<svg class="overview-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6M21 21v-3a6 6 0 0 0-4-5.66"/></svg>','会员':'<svg class="overview-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="2" y="4" width="20" height="16" rx="3"/><circle cx="8" cy="10" r="2"/><path d="M5 16a3 3 0 0 1 6 0M15 9h4M15 13h4"/></svg>'};
function targetGap(id,targetId){const value=current(metrics[id]),target=current(metrics[targetId]);return (value/target-1)*100}
function coreRow(id,name,targetId,rateId,rateName){const m=metrics[id],rate=metrics[rateId],gap=targetGap(id,targetId),rateTarget=rateId==='receiptDiscountRate'?rate.target:current(metrics[targetId])/current(metrics.target)*100,rateGap=current(rate)-rateTarget;return `<div class="core-item"><button class="core-main" data-go="${id}" aria-label="${name}，查看分析"><span class="core-name">${name} <b class="${id==='receipt'?'':'orange'}">¥${fmt(current(m),m)}${unit(m).replace('元','')}</b></span><span class="core-target ${gap<0?'orange':''}">${signed(gap)}%</span>${comparison(m)}${comparison(m,'yoy')}<span class="core-arrow" aria-hidden="true">›</span></button><button class="core-secondary" data-go="${rateId}" aria-label="${rateName}，查看分析"><span>${rateName} ${fmt(current(rate),rate)}%</span><span>${signed(rateGap)}pp</span>${comparison(rate)}${comparison(rate,'yoy')}<span></span></button></div>`}
function groupOverview(){return `<section class="group-overview card" aria-label="集团概览"><div class="scale-grid">${[['stores','在营门店','门店'],['members','累计会员','会员'],['fulltime','员工数（正式工）','员工']].map(([id,name,icon])=>{const m=metrics[id];return `<button class="scale-metric" data-go="${id}"><div class="scale-number">${overviewIcons[icon]}<b>${fmt(current(m),m)}<small>${unit(m)}</small></b></div><div class="scale-name">${name}</div>${changes(m)}</button>`}).join('')}</div><div class="core-panel"><div class="core-columns"><span>核心指标</span><span>目标对比</span><span>环比</span><span>同比</span><span></span></div>${coreRow('receipt','门店实收','target','receiptDiscountRate','折扣率')}${coreRow('profit','门店利润','profitTarget','profitShare','利润率')}${coreRow('groupProfit','集团利润','groupProfitTarget','groupProfitShare','集团利润率')}</div><p class="core-note">利润为预算测算；门店实收及门店利润同比按同店口径。点击指标查看明细。</p></section>`}
function overviewDetails(id){if(id==='stores')return overviewGroup('门店指标',overviewIcons['门店'],['building','area'],state.endDate?'期间坪效 · 按所选期间折算':(state.day==='day'?'日':state.day==='week'?'周':'月')+'坪效 · 按天数折算');if(id==='fulltime')return overviewGroup('员工指标',overviewIcons['员工'],['hourly','efficiency']);if(id==='members')return overviewGroup('会员指标',overviewIcons['会员'],['active','activeRate'],'活跃会员：最近3个月消费次数大于等于1的会员');return ''}
function home(){return `${section('集团概览')}${groupOverview()}${section('集团体检','四大核心能力')}<div class="health-grid">${['cash','sameStore','profitGrowth','opening'].map(id=>{const m=metrics[id];return `<button class="health-card" data-go="${id}"><div class="health-title"><i>${{cash:'▣',sameStore:'⌁',profitGrowth:'◴',opening:'↗'}[id]}</i><b>${m.name}</b><span>${m.caption}</span><em>›</em></div><div class="health-number ${current(m)<m.target?'orange':''}">${m.id==='profitGrowth'&&current(m)>0?'+':''}${fmt(current(m),m)}<small>${unit(m)}</small></div><div class="metric-hint">目标 ${m.lower?'≤':'≥'}${m.target}${m.unit}</div>${changes(m)}</button>`}).join('')}</div>${section('巡店建议','利润 × 巡店得分')}<div class="quadrant-grid">${quadrants.slice(0,4).map(([id,name,n,desc,color])=>`<button class="quadrant" data-go="${id}"><div class="row"><b class="pill ${color}">${name}</b><strong class="${color}">${n}<small>家</small></strong></div><p>${desc}</p>${changes(metrics[id])}</button>`).join('')}</div><button class="pending-class" data-go="unrated">另有 197 家待评估，四类已评估合计 202 家<span>›</span></button>${section('门店引流','7种方式 · 流量及占比')}<div class="card card-pad"><button class="receipt-progress" data-go="traffic"><span>已归因总流量 ›</span><b>${money(current(metrics.traffic))}<small>人次</small></b></button><div class="explain">最后有效触点归因 · 每次访问仅计入一个来源</div></div><div class="card">${attraction.map(([id,name,p],i)=>`<button class="flow-row" data-go="${id}"><div class="row"><span><i class="flow-index">${i+1}</i>${name} ›</span><b>${money(current(metrics[id]))}<small>${metrics[id].unit}</small></b></div><div class="flow-bottom"><div class="track"><div style="width:${p*100/.26}%"></div></div><span>${(p*100).toFixed(1)}%</span></div></button>`).join('')}</div>${section('门店损益','占实收比例 · 环比 · 同店同比')}<div class="card pnl">${['receipt',...costs.map(x=>x[0]),'profit'].map(id=>{const m=metrics[id];return `<button class="pnl-row ${id==='profit'?'profit-total':''}" data-go="${id}"><div class="row"><span>${id==='receipt'?'实收':m.name} ›</span><b>¥ ${money(current(m))}</b></div><div class="pnl-meta"><span>占实收 <b>${(current(m)/current(metrics.receipt)*100).toFixed(1)}%</b></span>${changes(m)}</div></button>`}).join('')}</div>${footer()}`}
const visits=[{market:'华南市场',store:'海滨示范店',priority:'优先巡查',color:'red',issue:'利润率 −2.3%，巡店得分 68 分',action:'重点核查食材耗用、损耗与当班操作。',owner:'区域督导 · 建议24小时内',metric:'problem'}, {market:'华东市场',store:'中心示范店',priority:'重点关注',color:'orange',issue:'利润率 15.2%，巡店得分 72 分',action:'核查卫生、服务及标准执行，预防利润下滑。',owner:'运营负责人 · 建议3日内',metric:'hidden'}, {market:'华中市场',store:'大学城示范店',priority:'经营辅导',color:'blue',issue:'利润率 5.1%，巡店得分 91 分',action:'复核商圈客流、商品结构和排班效率。',owner:'市场负责人 · 建议本周',metric:'potential'}];
function receiptOverview(){return `<div class="card metric-grid">${metricCard('target')}<div class="group-metric"><div class="metric-label">实际实收</div><div class="metric-number">${fmt(current(metrics.receipt),metrics.receipt)}<small>${unit(metrics.receipt)}</small></div>${changes(metrics.receipt)}</div></div><div class="card card-pad"><button class="receipt-progress" data-go="attainment"><span>实收达成率 ›</span><b>${fmt(current(metrics.attainment),metrics.attainment)}%</b></button><div class="big-track"><div style="width:${current(metrics.attainment)}%;background:var(--blue)"></div></div><div class="explain">目标缺口 ¥ ${money(current(metrics.target)-current(metrics.receipt))}</div></div><div class="card metric-grid">${metricCard('receiptDiscountRate')}${metricCard('receiptDiscountRateTarget')}</div>${paymentChart()}<div class="card card-pad"><div class="definition receipt-definition">${metrics.receipt.formula}</div></div>`}
function paymentChart(){const colors=['#2d62d7','#447af5','#6e99f9','#92b2fb','#abc7fb','#c6d9fd','#d4e5ff','#e3eeff','#f2f7ff'];let offset=0;const rings=payments.map(([id,n,p],i)=>{const x=`<circle cx="90" cy="90" r="68" fill="none" stroke="${colors[i]}" stroke-width="21" pathLength="100" stroke-dasharray="${p*100} ${100-p*100}" stroke-dashoffset="${-offset}" transform="rotate(-90 90 90)"/>`;offset+=p*100;return x}).join('');return `<div class="card card-pad"><div class="chart-title">支付类型分布</div><div class="donut-wrap"><svg viewBox="0 0 180 180" role="img" aria-label="支付类型分布，美团团购54.5%、抖音券21.3%、微信支付11.2%等"><g>${rings}</g><text x="90" y="82" text-anchor="middle" fill="#929baa" font-size="12">总计</text><text x="90" y="108" text-anchor="middle" fill="#263246" font-size="23" font-weight="600">${fmt(current(metrics.receipt),metrics.receipt)}${unit(metrics.receipt)}</text></svg></div><div class="payment-legend">${payments.map(([id,n,p],i)=>`<button data-go="${id}"><i style="background:${colors[i]}"></i><span>${n}</span><b>${(p*100).toFixed(1)}%</b><em>›</em></button>`).join('')}</div></div>`}
function attribution(m){const now=current(m),before=previous(m),delta=now-before;
if(m.base){const numerator=metrics[m.base],denominator=metrics[m.denominator],oldN=previous(numerator),newN=current(numerator),oldD=previous(denominator),newD=current(denominator);return {note:'比例＝分子÷分母。先替换分子，再替换分母，两项贡献相加等于比例变化。',rows:[[numerator.name+'变化',(newN-oldN)/oldD*100],[denominator.name+'变化',newN*(1/newD-1/oldD)*100]]}}
if(m.id==='receipt'){const d=days(),old=state.comparison==='mom'?{guests:2000,price:100,orders:2600,avg:50}:{guests:1836,price:100,orders:2400,avg:50};return {note:'连环替代法：先数量、后价格。堂食与外卖差额相加等于实收总差额；此为数学拆解，不代表已证实的经营原因。',rows:[['堂食客流',(1800-old.guests)*old.price*d],['堂食客单价',1800*(100-old.price)*d],['外卖订单数',(2500-old.orders)*old.avg*d],['外卖单均价',2500*(48-old.avg)*d]],equations:[['堂食客流',old.guests*d,1800*d,'人次'],['堂食客单价',old.price,100,'元'],['外卖订单数',old.orders*d,2500*d,'单'],['外卖单均价',old.avg,48,'元']]}}
if(m.id==='groupProfit')return {note:'集团利润变化＝门店预算利润变化－集团预算费用变化。',rows:[['门店利润变化',current(metrics.profit)-previous(metrics.profit)],['集团预算费用变化',previous(metrics.groupCost)-current(metrics.groupCost)]]};
if(m.id==='profit'){return {note:'实收增减减去各项成本费用增减，合计即预算利润变化。各项均按同一周期和同一门店集合比较。',rows:[['实收变化',current(metrics.receipt)-previous(metrics.receipt)],...costs.map(([id,n])=>[n+'变化',previous(metrics[id])-current(metrics[id])])]}}
if(costs.some(x=>x[0]===m.id)){const oldRevenue=previous(metrics.receipt),oldRate=before/oldRevenue;return {note:'成本/费用＝实收规模×费用率。先固定原费率测算规模影响，再计算费率变化影响；合计与本项金额差额一致。',rows:[['经营规模变化',(current(metrics.receipt)-oldRevenue)*oldRate],['单位成本/费率变化',current(metrics.receipt)*(now/current(metrics.receipt)-oldRate)]]}}
if(m.id==='attainment'){const oldReceipt=previous(metrics.receipt),oldTarget=oldReceipt/(before/100);return {note:'达成率＝实际实收÷目标实收。先替换实收，再替换目标；影响以百分点表示。',rows:[['实际实收变化',(current(metrics.receipt)-oldReceipt)/oldTarget*100],['目标实收变化',current(metrics.receipt)*(1/current(metrics.target)-1/oldTarget)*100]]}}
if(m.id==='efficiency'){const oldReceipt=previous(metrics.receipt),oldHours=oldReceipt/before,newHours=current(metrics.receipt)/now;return {note:'人效＝实收÷有效工时。先替换实收，再替换工时，量化两者对人效的影响。',rows:[['实收变化',(current(metrics.receipt)-oldReceipt)/oldHours],['有效工时变化',current(metrics.receipt)*(1/newHours-1/oldHours)]]}}
if(m.id==='activeRate'){const oldActive=previous(metrics.active),oldMembers=oldActive/(before/100),newActive=current(metrics.active);return {note:'活跃占比＝活跃会员÷累计会员。先替换分子，再替换分母，影响以百分点表示。',rows:[['活跃会员变化',(newActive-oldActive)/oldMembers*100],['累计会员变化',newActive*(1/current(metrics.members)-1/oldMembers)*100]]}}
const weights=m.drivers.length===2?[1.25,-.25]:m.drivers.length===3?[1.1,-.3,.2]:[.4,.2,.25,.15];const rows=m.drivers.map((n,i)=>[n,delta*weights[i]]);if(m.kind==='stock'&&m.unit!=='%'){rows.forEach(x=>x[1]=Math.round(x[1]));rows[rows.length-1][1]=delta-rows.slice(0,-1).reduce((n,x)=>n+x[1],0)}return {note:'演示贡献分解：各项影响相加等于指标净变化；贡献权重为模拟值，实际应用需用明细数据计算验证。',rows}}
function chart(m){const v=current(m),b=previous(m);const values=Array.from({length:7},(_,i)=>i===6?v:i===5?b:b+(v-b)*(i+1)/7+Math.sin(i*1.7)*Math.abs(v-b)*.22);const max=Math.max(...values),min=Math.min(...values),pad=Math.max((max-min)*.3,Math.abs(v)*.015,1),lo=min-pad,hi=max+pad;const pt=(n,i)=>[34+i*46,139-(n-lo)/(hi-lo)*108];const coords=values.map(pt);const labels=values.map((_,i)=>{if(state.day==='month'){const d=parseDate(dateRange().end);return iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()-(6-i)*periodMonths(),1))).slice(0,7)}const step=state.day==='week'?periodWeeks()*7:days();return shiftDate(dateRange().end,-(6-i)*step).slice(5).replace('-','/')});const chosen=state.point===null?6:Math.max(0,Math.min(6,state.point));return `<div class="trend-readout"><span>${labels[chosen]} ${state.day==='day'?'日':state.day==='week'?'周':'月'}度示例</span><strong>${fmt(values[chosen],m,false)} <small>${m.unit}</small></strong></div><svg viewBox="0 0 340 171" class="chart" role="img" aria-label="${m.name}最近7个${state.day==='day'?'日':state.day==='week'?'周':'月'}度点趋势">${[0,1,2,3].map(i=>`<line x1="34" x2="316" y1="${31+i*36}" y2="${31+i*36}" stroke="#e6ecf5" stroke-dasharray="3 3"/><text x="28" y="${35+i*36}" text-anchor="end" class="chart-label">${Math.abs(hi)>10000?((hi-(hi-lo)*i/3)/10000).toFixed(1)+'万':(hi-(hi-lo)*i/3).toFixed(m.decimals)}</text>`).join('')}<polyline points="${coords.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#4b89f6" stroke-width="2.2"/>${coords.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="${i===chosen?4:2.5}" fill="#4b89f6" stroke="white"/>`).join('')}${labels.map((l,i)=>`<text x="${34+i*46}" y="163" text-anchor="middle" class="chart-label">${l}</text>`).join('')}</svg><div class="chart-points" aria-label="查看趋势点">${labels.map((l,i)=>`<button data-point="${i}" class="${i===chosen?'active':''}">${l}</button>`).join('')}</div><div class="explain">最近7个${state.day==='day'?'日':state.day==='week'?'周':'月'}度示例点${state.endDate||state.day==='week'?` · 每点为${state.day==='month'?periodMonths()+'个月':days()+'天'}的同口径汇总，日期为期末`:''} · 点击日期查看数值</div>`}
function detail(id){const m=metrics[id],v=current(m),b=previous(m),delta=v-b,a=attribution(m);const deltaUnit=m.kind==='rate'?'个百分点':m.unit;return `${filter()}<div class="detail-context">集团汇总 <span>${rangeText(dateRange())}</span></div>${id==='receipt'?receiptOverview():`<div class="card card-pad">${m.base||m.shareMetric?`<div class="tabs"><button data-go="${m.base||m.id}" class="${m.base?'':'active'}">${m.unit==='单'||(m.base&&metrics[m.base].unit==='单')?'订单量':m.unit==='人次'||(m.base&&metrics[m.base].unit==='人次')?'流量':'金额'}</button><button data-go="${m.base?m.id:m.shareMetric}" class="${m.base?'active':''}">占比</button></div>`:''}<div class="metric-label">${m.name}</div><div class="detail-value">${fmt(v,m)}<small>${unit(m)}</small></div>${changes(m)}${m.share!==undefined?`<div class="metric-hint">${costs.some(x=>x[0]===m.id)?'占实收':payments.some(x=>x[0]===m.id)?'支付占比':'流量占比'} ${(m.share*100).toFixed(1)}%</div>`:''}<div class="definition">${m.formula}</div></div>`}${id==='stores'?`${section('在营门店类型')}<div class="card"><div class="ownership">${owners.map(([id,n,v])=>`<button data-go="${id}"><span>${n} ›</span><b>${v}<small>家</small></b></button>`).join('')}</div></div>`:''}${overviewDetails(id)}${id==='profit'?`<div class="card metric-grid">${metricCard('profitTarget')}${metricCard('profitShare')}</div>`:id==='groupProfit'?`<div class="card metric-grid">${metricCard('groupProfitTarget')}${metricCard('groupCost')}</div>`:''}${section('01 指标趋势')}<div class="card card-pad">${chart(m)}</div>${section('02 量化归因分析')}<div class="card card-pad"><div class="tabs"><button data-compare="mom" class="${state.comparison==='mom'?'active':''}">环比</button><button data-compare="yoy" class="${state.comparison==='yoy'?'active':''}">${m.sameStore?'同店同比':'同比'}</button></div><div class="explain">对比期：${rangeText(compareRange())}</div><div class="bridge-summary"><div><span>对比期</span><b>${fmt(b,m,false)}</b></div><em>→</em><div><span>本期</span><b>${fmt(v,m,false)}</b></div><div><span>净变化 / ${deltaUnit}</span><b class="${delta<0?'red':'green'}">${delta>0?'+':''}${fmt(delta,m,false)}</b></div></div><div class="explain">${a.note} 显示值四舍五入，可能存在尾差。</div></div><div class="card">${a.rows.map(([name,n])=>`<div class="contribution-row"><div class="row"><span>${name}</span><b class="${n<0?'red':'green'}">${n>0?'+':''}${fmt(n,m,false)}<small>${deltaUnit}</small></b></div><div class="contribution-bar"><span style="width:${Math.min(100,Math.abs(n)/(Math.max(...a.rows.map(x=>Math.abs(x[1])))||1)*100)}%;background:${n<0?'#f16a77':'#51bc9b'}"></span></div></div>`).join('')}<div class="contribution-total">贡献合计 <b>${delta>0?'+':''}${fmt(a.rows.reduce((n,x)=>n+x[1],0),m,false)} ${deltaUnit}</b></div></div>${a.equations?`<div class="card table-wrap"><table><thead><tr><th>实收驱动因子</th><th>对比期</th><th>本期</th></tr></thead><tbody>${a.equations.map(([n,b,v,u])=>`<tr><td>${n} / ${u}</td><td>${money(b)}</td><td>${money(v)}</td></tr>`).join('')}</tbody></table><div class="card-pad explain">堂食：${money(1800*days())}人次 × 100元 = ${money(flow(180000))}元<br>外卖：${money(2500*days())}单 × 48元 = ${money(flow(120000))}元</div></div>`:''}<button class="back-home" data-go="home">返回集团看板</button>${footer()}`}
function visitDetail(index){const v=visits[index]||visits[0];return `${filter()}<div class="card card-pad"><div class="row"><h2 class="visit-heading">${v.store}</h2><span class="pill ${v.color}">${v.priority}</span></div><p class="minor muted">${v.market} · ${v.owner}</p><p class="minor">${v.issue}</p></div>${section('巡店重点')}<div class="card card-pad"><p class="minor">${v.action}</p><ol class="visit-checklist"><li>核对异常指标的原始凭证、班次和统计口径。</li><li>现场确认原因，记录证据与负责岗位。</li><li>约定整改时限，复查同口径指标及执行结果。</li></ol></div>${section('量化依据')}<div class="card">${metricCard(v.metric)}${metricCard('profit')}${metricCard('food')}</div><div class="notice">该门店案例为模拟。下方指标穿透为集团口径，用于展示趋势与归因流程。</div><button class="back-home" data-go="${v.metric}">查看${metrics[v.metric].name}趋势与归因 ›</button>${footer()}`}
function dialogs(){const month=state.day==='month',week=state.day==='week',type=month?'month':'date',r=dateRange(),value=v=>month?v.slice(0,7):v,min=month?'2020-01':'2020-01-01',max=month?'2035-12':week?shiftDate(todayDate(),-1):'2035-12-31';return `<dialog id="date-dialog" aria-labelledby="date-dialog-title"><form id="date-form"><h3 id="date-dialog-title">${month?'选择月份期间':week?'选择周期间':'选择日期区间'}</h3><div class="date-range-fields"><label for="date-input">${month?'开始月份':'开始日期'}</label><input id="date-input" type="${type}" value="${value(week?r.start:state.date)}" min="${min}" max="${max}" required><label for="date-end">${month?'结束月份':'结束日期'}</label><input id="date-end" type="${type}" value="${value(r.end)}" min="${min}" max="${max}" required></div><p class="date-range-help">${month?'包含开始与结束月份，按完整自然月汇总。':week?'起止日期按所在周统计：历史周为周一至周日，当前周为周一至昨天（北京时间）。':'包含开始与结束日期；选择同一天可筛选单日。'}</p><p id="date-error" role="alert" hidden></p><div class="date-actions"><button type="button" id="date-cancel">取消</button><button type="submit">确定</button></div></form></dialog>`}
function applyDateRange(e){e.preventDefault();const month=state.day==='month',week=state.day==='week',start=document.getElementById('date-input').value,end=document.getElementById('date-end').value,first=month?start+'-01':start,last=month?end+'-01':end,error=document.getElementById('date-error');if(!validDate(first)||!validDate(last)||first>last){error.textContent=month?'结束月份不能早于开始月份。':'结束日期不能早于开始日期。';error.hidden=false;return}if(week&&last>=todayDate()){error.textContent='周统计仅包含昨天及以前的日期。';error.hidden=false;return}state.date=week?weekStart(first):first;state.endDate=week?(weekStart(first)===weekStart(last)?null:weekStart(last)):first===last?null:last;state.point=null;persist();render();document.getElementById('date-open').focus()}
function render(){if(!['day','week','month'].includes(state.day))state.day='day';if(!validDate(state.date))state.date='2026-09-18';if(state.day==='week'){const latest=shiftDate(todayDate(),-1);if(state.date>latest){state.date=latest;state.endDate=null}if(state.endDate&&state.endDate>latest)state.endDate=latest}const id=route(),isMetric=!!metrics[id],isVisit=id.startsWith('visit-'),isHome=!isMetric&&!isVisit;const title=isHome?'老板看板':id==='receipt'?'门店实收':id==='profit'?'门店利润':isMetric?metrics[id].name:'巡店建议';document.title=title+' · 集团演示';document.getElementById('app').classList.toggle('home-view',isHome);document.getElementById('app').innerHTML=(isHome?homeHeader(title):`<header><button id="back" aria-label="返回上一页">‹</button><h1>${title}</h1><span class="demo">DEMO</span></header>`)+(isHome?home():isMetric?detail(id):visitDetail(Number(id.slice(6))))+dialogs();document.querySelectorAll('[data-go]').forEach(e=>e.onclick=()=>go(e.dataset.go));document.querySelectorAll('[data-date-type]').forEach(e=>e.onclick=()=>{state.day=e.dataset.dateType;state.endDate=null;state.point=null;persist();render();document.getElementById('date-control').open=true;document.querySelector('[data-date-type="'+state.day+'"]').focus()});document.querySelectorAll('[data-compare]').forEach(e=>e.onclick=()=>{state.comparison=e.dataset.compare;persist();render()});document.querySelectorAll('[data-point]').forEach(e=>e.onclick=()=>{state.point=Number(e.dataset.point);render()});document.querySelectorAll('[data-date-value]').forEach(e=>e.onclick=()=>{state.date=e.dataset.dateValue;state.endDate=null;state.point=null;persist();render();document.getElementById('date-open').focus()});document.getElementById('date-other').onclick=()=>{document.getElementById('date-control').open=false;document.getElementById('date-dialog').showModal()};document.getElementById('date-cancel').onclick=()=>document.getElementById('date-dialog').close();document.getElementById('date-form').onsubmit=applyDateRange;const back=document.getElementById('back');if(back)back.onclick=()=>history.state?.depth>0?history.back():go('home')}
document.addEventListener('click',e=>{const picker=document.getElementById('date-control');if(picker&&!e.target.closest('.date-control'))picker.open=false});document.addEventListener('keydown',e=>{const picker=document.getElementById('date-control');if(e.key==='Escape'&&picker?.open){picker.open=false;document.getElementById('date-open').focus()}});
history.scrollRestoration='manual';if(history.state?.filters)Object.assign(state,{endDate:null},history.state.filters);window.addEventListener('popstate',()=>{if(history.state?.filters)Object.assign(state,{endDate:null},history.state.filters);render();window.scrollTo(0,history.state?.scroll||0)});render();persist();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_dashboard_filters',description:'切换集团看板的日期类型与日期，所有指标同步展示。',inputSchema:{type:'object',properties:{day:{type:'string',enum:['day','week','month']},date:{type:'string'}},required:['day','date'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!['day','week','month'].includes(input.day)||!validDate(input.date))throw Error('日期无效');Object.assign(state,{day:input.day,date:input.date,endDate:null,point:null});persist();render();return {range:dateRange(),simulated:true}}})).catch(()=>{});}catch{}}
